const STORAGE_KEY = 'fieldnotes-english-v1';
const defaults = {
  minutes: 0, sessions: 0, streak: 0, lastPractice: '', practicedDays: [], completed: [],
  draft: '', drafts: {}, readingResponses:{}, diagnostic: null, courseLesson: 'introduction', speakingDrill:{index:0,completed:[]}, roleplay:{scenario:0,turn:0,showModel:false},
  mock: {writtenText:'',writtenDeadline:null,writtenAttempts:[],oralIndex:0,oralDeadline:null,oralAttempts:[]}, words: [
    {word:'watershed',meaning:'cuenca hidrográfica',example:'The watershed connects communities upstream and downstream.'},
    {word:'stakeholder',meaning:'actor involucrado / parte interesada',example:'Every stakeholder should have a voice in the process.'},
    {word:'upstream',meaning:'aguas arriba',example:'Activities upstream can affect water quality downstream.'},
    {word:'well-being',meaning:'bienestar',example:'The project aims to improve community well-being.'},
    {word:'to monitor',meaning:'monitorear / hacer seguimiento',example:'We monitor water quality throughout the year.'}
  ]
};
let state = loadState();
let toastTimer;
let mediaRecorder = null;
let recordedChunks = [];
let audioUrl = '';
let timerInterval = null;
let recordSeconds = 0;
let recordingStream = null;
let promptIndex = 0;
let readingCorrect = false;
let listeningCorrect = false;
let listeningPlayed = false;
const courseUnits = window.COURSE_UNITS || [];
let currentUnit = courseUnits.find(unit=>unit.id===state.courseLesson) || courseUnits[0];
if(!state.drafts)state.drafts={};
if(!state.readingResponses)state.readingResponses={};
state.mock={...defaults.mock,...(state.mock||{})};
if(!Array.isArray(state.mock.writtenAttempts))state.mock.writtenAttempts=[];
if(!Array.isArray(state.mock.oralAttempts))state.mock.oralAttempts=[];
state.speakingDrill={...defaults.speakingDrill,...(state.speakingDrill||{})};if(!Array.isArray(state.speakingDrill.completed))state.speakingDrill.completed=[];state.speakingDrill.index=Math.min(6,Math.max(0,Number(state.speakingDrill.index)||0));
state.roleplay={...defaults.roleplay,...(state.roleplay||{})};state.roleplay.scenario=Math.min(2,Math.max(0,Number(state.roleplay.scenario)||0));state.roleplay.turn=Math.min(2,Math.max(0,Number(state.roleplay.turn)||0));
state.words.forEach(word=>{if(!Number.isFinite(word.dueAt))word.dueAt=Date.now();if(!Number.isFinite(word.intervalDays))word.intervalDays=0;if(!Number.isFinite(word.repetitions))word.repetitions=0});
if(state.draft&&!state.drafts.introduction)state.drafts.introduction=state.draft;

function loadState(){try{return {...defaults,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch{return {...defaults}}}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderStats();if(document.getElementById('course-units'))renderCourseUnits()}
function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function markPractice(minutes,label){const today=todayKey();state.minutes+=minutes;state.sessions+=1;if(state.lastPractice!==today){const prev=new Date();prev.setDate(prev.getDate()-1);const prevKey=`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}-${String(prev.getDate()).padStart(2,'0')}`;state.streak=state.lastPractice===prevKey?state.streak+1:1;state.lastPractice=today;state.practicedDays=[...new Set([...state.practicedDays,today])].slice(-30)}if(!state.completed.includes(label))state.completed.push(label);saveState();showToast('¡Práctica guardada! Buen trabajo.')}
function renderStats(){document.getElementById('minutes-total').textContent=state.minutes;document.getElementById('words-count').textContent=state.words.length;document.getElementById('streak-count').textContent=state.streak;document.getElementById('plan-minutes').textContent=`${state.minutes} min`;document.getElementById('plan-sessions').textContent=state.sessions;document.getElementById('vocab-total').textContent=String(state.words.length).padStart(2,'0');const due=state.words.filter(word=>(word.dueAt||0)<=Date.now()).length;document.getElementById('vocab-due-count').textContent=due;const monday=new Date();monday.setDate(monday.getDate()-(monday.getDay()+6)%7);monday.setHours(0,0,0,0);const practicedThisWeek=state.practicedDays.filter(k=>new Date(k+'T12:00:00')>=monday).length;const done=Math.min(5,practicedThisWeek);document.getElementById('plan-week-complete').textContent=`${done} / 5`;const week=document.getElementById('week-dots');week.innerHTML='';const days=['L','M','X','J','V'];days.forEach((day,i)=>{const date=new Date();const offset=(date.getDay()+6)%7;date.setDate(date.getDate()-offset+i);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const dot=document.createElement('span');dot.className='week-dot'+(state.practicedDays.includes(key)?' done':'');dot.textContent=state.practicedDays.includes(key)?'✓':day;week.append(dot)});document.getElementById('week-summary').textContent=`${practicedThisWeek} de 5 días`}
function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),2400)}
function navigate(page){const target=document.getElementById(`page-${page}`);if(!target)return;document.querySelectorAll('.page').forEach(el=>el.classList.remove('active-page'));target.classList.add('active-page');document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===page));document.getElementById('crumb-current').textContent=page.toUpperCase();history.replaceState(null,'',`#${page}`);window.scrollTo({top:0,behavior:'smooth'});if(page==='vocabulario')renderVocab();if(page==='escritura')document.getElementById('writing-draft').value=state.drafts[currentUnit.id]||'';if(page==='curso')renderCourseUnits()}
document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();navigate(el.dataset.page)}));document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.go)));window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'inicio'));
const hash=location.hash.slice(1);if(hash&&document.getElementById(`page-${hash}`))navigate(hash);
const now=new Date();document.getElementById('today-label').textContent=now.toLocaleDateString('es-PE',{weekday:'short',day:'2-digit',month:'short'}).toUpperCase();
renderStats();

function renderCourseUnits(){const list=document.getElementById('course-units');if(!list)return;list.innerHTML='';courseUnits.forEach(unit=>{const card=document.createElement('article');card.className='course-card';const meta=document.createElement('div');meta.className='course-card-meta';meta.innerHTML=`<span>SEMANA ${unit.week}</span><span>${unit.level}</span>`;const title=document.createElement('h3');title.textContent=unit.title;const focus=document.createElement('p');focus.textContent=unit.focus;const skills=document.createElement('div');skills.className='course-skills';skills.innerHTML='<span>READ</span><span>LISTEN</span><span>WRITE</span><span>SPEAK</span>';const done=['reading','listening','writing','speaking'].filter(skill=>state.completed.includes(`${skill}:${unit.id}`)).length;const progress=document.createElement('div');progress.className='course-card-progress';progress.textContent=done===4?'Unidad completada':`${done} de 4 prácticas completadas`;const open=document.createElement('button');open.className='course-open';open.dataset.unit=unit.id;open.textContent=done===4?'Repasar unidad →':'Abrir unidad →';open.addEventListener('click',()=>{selectUnit(unit.id);navigate('lectura')});card.append(meta,title,focus,skills,progress,open);list.append(card)})}
function renderUnit(unit){if(!unit)return;const read=document.querySelector('.reading-panel');read.querySelector('.reading-meta span:first-child').textContent=`UNIT ${unit.week} · READING`;read.querySelector('.reading-meta span:last-child').textContent=unit.level;read.querySelector('h2').textContent=unit.reading.title;const readParas=read.querySelectorAll(':scope > p');readParas[0].textContent=unit.reading.lead;unit.reading.paragraphs.forEach((paragraph,index)=>{if(readParas[index+1])readParas[index+1].textContent=paragraph});const guide=document.querySelector('.lesson-side .side-card p');guide.textContent=unit.reading.guide;document.querySelector('.side-spanish').textContent=unit.reading.guideEs;document.querySelector('.comprehension-card h3').textContent=unit.reading.question;const options=document.getElementById('reading-options');options.innerHTML='';unit.reading.options.forEach(option=>{const button=document.createElement('button');button.dataset.answer=String(option.correct);button.textContent=option.text;options.append(button)});readingCorrect=false;document.getElementById('quiz-feedback').textContent='';const vocab=document.querySelector('.reading-vocab');vocab.innerHTML='<span>KEY TERMS · SELECT TO SAVE</span>';unit.vocab.forEach(item=>{const button=document.createElement('button');button.dataset.courseVocab=item.word;button.textContent=item.word;const plus=document.createElement('b');plus.textContent='+';button.append(plus);vocab.append(button)});document.querySelector('.writing-prompt .prompt-tag').textContent=unit.writing.type;document.querySelector('.writing-prompt h2').textContent=unit.writing.prompt;document.querySelector('.writing-prompt>p').textContent=`Word target: ${unit.writing.prompt.match(/\b\d+–\d+\b/)?.[0]||'100–150 words'}. Use the guide below to organize your ideas.`;document.querySelector('.prompt-spanish').textContent=unit.writing.translation;const structure=document.querySelector('.structure-tip');structure.innerHTML='<strong>Una estructura útil</strong>';unit.writing.structure.forEach((step,index)=>{const span=document.createElement('span');span.textContent=`${String(index+1).padStart(2,'0')} · ${step}`;structure.append(span)});document.getElementById('writing-draft').value=state.drafts[unit.id]||'';updateWordCount();document.getElementById('oral-prompt').textContent=unit.speaking[0].q;document.getElementById('oral-translation').textContent=unit.speaking[0].es;document.querySelector('.prompt-toolbar .side-label').innerHTML=`INTERVIEW PRACTICE · <b id="prompt-index">01</b> / ${String(unit.speaking.length).padStart(2,'0')}`;promptIndex=0;document.querySelectorAll('.unit-select').forEach(select=>select.value=unit.id);document.getElementById('record-status').textContent='LISTA PARA GRABAR';document.getElementById('listening-unit-label').textContent=`UNIT ${unit.week} · LISTENING`;document.getElementById('listening-title').textContent=unit.listening.title;document.getElementById('listening-question').textContent=unit.listening.question;const listeningOptions=document.getElementById('listening-options');listeningOptions.innerHTML='';unit.listening.options.forEach((option,index)=>{const button=document.createElement('button');button.dataset.option=String(index);button.textContent=option;listeningOptions.append(button)});document.getElementById('listening-feedback').textContent='';document.getElementById('listening-transcript').textContent=unit.listening.script;document.getElementById('listening-transcript').hidden=true;document.getElementById('show-transcript').disabled=true;document.getElementById('show-transcript').innerHTML='Ver transcripción <span>＋</span>';listeningCorrect=false;listeningPlayed=false}
function updateReadingChallengeCount(unitId){const answer=document.getElementById('reading-challenge-answer');const count=answer.value.trim()?answer.value.trim().split(/\s+/).length:0;document.getElementById('reading-challenge-count').textContent=count+' words';document.getElementById('reading-challenge-saved').textContent='Guardada en este dispositivo';state.readingResponses[unitId]=answer.value;localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
function renderReadingChallenge(unit){const box=document.getElementById('reading-challenge');const task=unit.reading.reflection;box.hidden=!task;if(!task)return;document.getElementById('reading-challenge-prompt').textContent=task.prompt;document.getElementById('reading-challenge-translation').textContent=task.translation;const answer=document.getElementById('reading-challenge-answer');answer.value=state.readingResponses[unit.id]||'';const count=answer.value.trim()?answer.value.trim().split(/\s+/).length:0;document.getElementById('reading-challenge-count').textContent=count+' words';document.getElementById('reading-challenge-saved').textContent=count?'Guardada en este dispositivo':'Se guarda localmente mientras escribes'}
document.getElementById('reading-challenge-answer').addEventListener('input',()=>updateReadingChallengeCount(currentUnit.id));function selectUnit(id){const chosen=courseUnits.find(unit=>unit.id===id);if(!chosen)return;if(currentUnit&&document.getElementById('writing-draft'))state.drafts[currentUnit.id]=document.getElementById('writing-draft').value;currentUnit=chosen;state.courseLesson=id;promptIndex=0;renderUnit(currentUnit);renderReadingChallenge(currentUnit);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderCourseUnits()}
function installUnitSelectors(){['lectura','listening','escritura','speaking'].forEach(pageName=>{const page=document.getElementById(`page-${pageName}`);const row=document.createElement('div');row.className='unit-select-row';const label=document.createElement('label');label.textContent='UNIDAD DE PRÁCTICA';const select=document.createElement('select');select.className='unit-select';select.setAttribute('aria-label','Elegir unidad del curso');courseUnits.forEach(unit=>{const option=document.createElement('option');option.value=unit.id;option.textContent=`${unit.week} · ${unit.title}`;select.append(option)});select.addEventListener('change',()=>selectUnit(select.value));label.append(select);row.append(label);page.querySelector('.module-header').after(row)})}

function showDiagnosticResult(result){if(!result)return;document.getElementById('diagnostic-score').innerHTML=`${result.score} <small>/ 10</small>`;document.getElementById('result-title').textContent=result.title;document.getElementById('result-copy').textContent=result.copy;const button=document.getElementById('diagnostic-next');button.hidden=false;button.onclick=()=>navigate(result.next)}
if(state.diagnostic)showDiagnosticResult(state.diagnostic);
document.getElementById('diagnostic-form').addEventListener('submit',event=>{event.preventDefault();const answers={q1:'b',q2:'c',q3:'a',q4:'b',q5:'c',q6:'b',q7:'a',q8:'a',q9:'c',q10:'b'};const data=new FormData(event.currentTarget);const score=Object.entries(answers).reduce((total,[key,value])=>total+(data.get(key)===value?1:0),0);let result;if(score<=3)result={score,title:'Construyamos una base firme.',copy:'Empieza con frases frecuentes, verbos básicos y vocabulario cotidiano. Practica speaking con respuestas cortas y lectura sencilla antes de subir la dificultad.',next:'vocabulario'};else if(score<=6)result={score,title:'Ya tienes una base en desarrollo.',copy:'Refuerza tiempos verbales, conectores y comprensión global. Alterna lecturas breves con respuestas orales de un minuto.',next:'lectura'};else if(score<=8)result={score,title:'Tu comprensión va tomando forma.',copy:'Trabaja precisión gramatical y vocabulario técnico. Explica ideas de GIRH, resume textos y estructura respuestas de examen.',next:'escritura'};else result={score,title:'Buen resultado en gramática y lectura.',copy:'Este puntaje no comprueba nivel avanzado por sí solo. Prioriza producción oral, escritura argumentativa y simulaciones con tiempo.',next:'speaking'};state.diagnostic=result;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));showDiagnosticResult(result)});

function speak(text,rate=.88){if(!('speechSynthesis'in window)){showToast('La lectura en voz alta no está disponible en este navegador.');return}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=rate;window.speechSynthesis.speak(utterance)}
document.getElementById('quote-audio').addEventListener('click',()=>speak(document.getElementById('daily-quote').textContent));
document.getElementById('listen-prompt').addEventListener('click',()=>speak(currentUnit.speaking[promptIndex].q));
document.querySelectorAll('.phrase').forEach(btn=>btn.addEventListener('click',()=>speak(btn.dataset.say)));
function setSpeakingPrompt(index){promptIndex=(index+currentUnit.speaking.length)%currentUnit.speaking.length;document.getElementById('oral-prompt').textContent=currentUnit.speaking[promptIndex].q;document.getElementById('oral-translation').textContent=currentUnit.speaking[promptIndex].es;document.getElementById('prompt-index').textContent=String(promptIndex+1).padStart(2,'0')}
document.getElementById('next-prompt').addEventListener('click',()=>setSpeakingPrompt(promptIndex+1));

function reviewEnglishDraft(text,minWords,maxWords,output){const content=text.trim();output.replaceChildren();output.hidden=false;if(!content){output.textContent='Escribe una respuesta antes de revisarla.';return}const words=content.split(/\s+/).length;const findings=[];if(words<minWords)findings.push(`Longitud: tienes ${words} palabras; añade ${minWords-words} para llegar al mínimo orientativo.`);else if(words>maxWords)findings.push(`Longitud: tienes ${words} palabras; reduce al menos ${words-maxWords} para entrar en el rango orientativo.`);else findings.push(`Longitud: ${words} palabras, dentro del rango orientativo.`);const paragraphs=content.split(/\n\s*\n/).filter(part=>part.trim());findings.push(paragraphs.length>1?'Estructura: separaste las ideas en párrafos.':'Estructura: considera separar la respuesta en párrafos para que cada idea principal se entienda.');findings.push(/\b(for example|because|however|therefore|although|first|also|in addition|as a result)\b/i.test(content)?'Conectores: ya incluiste al menos un conector. Revisa que exprese la relación que quieres comunicar.':'Conectores: prueba añadir uno que conecte tus ideas, como “because”, “however” o “for example”.');findings.push('Contenido: comprueba que tu primera oración responda directamente a la consigna y que incluyas un ejemplo relevante.');const errors=[[/\bI am agree\b/i,'Usa “I agree”, sin “am”.'],[/\b(he|she|it) have\b/i,'Con he, she o it, usa “has”.'],[/\bpeople is\b/i,'“People” es plural: usa “people are”.'],[/\bdiscuss about\b/i,'“Discuss” va directo con el tema: quita “about”.'],[/\bdepend of\b/i,'La expresión usual es “depend on”.'],[/\b(informations|advices)\b/i,'“Information” y “advice” normalmente no llevan plural en inglés.'],[/\bmore (better|easier|worse)\b/i,'Evita “more” antes de “better”, “easier” o “worse”.'],[/(?:^|[.!?]\s+)[a-z]/,'Revisa que cada oración empiece con mayúscula.']];let found=0;errors.forEach(([pattern,message])=>{if(pattern.test(content)){findings.push(`Precisión: ${message}`);found++}});if(!found)findings.push('Precisión: no detecté los errores frecuentes que revisa esta guía; eso no garantiza que el texto esté libre de errores.');const title=document.createElement('strong');title.textContent='Revisión local orientativa';const list=document.createElement('ul');findings.forEach(item=>{const li=document.createElement('li');li.textContent=item;list.append(li)});const note=document.createElement('small');note.textContent='La guía comprueba longitud y algunos patrones frecuentes. No evalúa gramática completa, relevancia ni equivale a una nota de examen.';output.append(title,list,note)}

const speakingDrills=[
  {title:'Preséntate',task:'Di tu nombre, qué estudiaste y por qué te interesa el agua.',en:'My name is ___. I studied ___. I am interested in water because ___.',es:'Me llamo ___. Estudié ___. Me interesa el agua porque ___.',model:'My name is Ana. I studied environmental engineering. I am interested in water because it is important for every community.'},
  {title:'Habla de tu experiencia',task:'Menciona una actividad de campo, estudio o trabajo que hayas realizado.',en:'I have experience in ___. I learned how to ___.',es:'Tengo experiencia en ___. Aprendí a ___.',model:'I have experience in field activities. I learned how to collect information carefully and work with a team.'},
  {title:'Explica una cuenca',task:'Define watershed con palabras sencillas y da un ejemplo.',en:'A watershed is an area where ___. For example, ___.',es:'Una cuenca es un área donde ___. Por ejemplo, ___.',model:'A watershed is an area where water drains to the same river or lake. For example, rain can flow from hills into a shared river.'},
  {title:'Describe el puesto',task:'Explica una tarea que podría realizar una persona asistente técnica.',en:'A technical assistant can ___. This helps the team ___.',es:'Una persona asistente técnica puede ___. Esto ayuda al equipo a ___.',model:'A technical assistant can organize field information. This helps the team understand local conditions and plan its next steps.'},
  {title:'Explica un dato',task:'Resume un hallazgo sin afirmar más de lo que muestran los datos.',en:'The data show ___. We need more information to ___.',es:'Los datos muestran ___. Necesitamos más información para ___.',model:'The data show lower river flow at this site. We need more information to understand the causes.'},
  {title:'Participa en una reunión',task:'Expresa acuerdo parcial y formula una pregunta respetuosa.',en:'I understand your point. Could you explain ___? One concern is ___.',es:'Entiendo tu punto. ¿Podrías explicar ___? Una preocupación es ___.',model:'I understand your point. Could you explain how this option affects downstream users? One concern is the cost of monitoring.'},
  {title:'Responde una entrevista',task:'Conecta tu interés, una fortaleza y tu aporte al programa.',en:'I am interested in this role because ___. I can contribute by ___.',es:'Me interesa este puesto porque ___. Puedo contribuir ___.',model:'I am interested in this role because it combines technical work and collaboration. I can contribute by organizing information and listening to local stakeholders.'}
];
function renderSpeakingDrill(){const index=state.speakingDrill.index;const drill=speakingDrills[index];document.getElementById('drill-title').textContent=`Día ${index+1} · ${drill.title}`;document.getElementById('drill-task').textContent=drill.task;document.getElementById('drill-english').textContent=drill.en;document.getElementById('drill-spanish').textContent=drill.es;document.getElementById('drill-count').textContent=`${state.speakingDrill.completed.length} / 7`;const complete=document.getElementById('drill-complete');complete.disabled=state.speakingDrill.completed.includes(index);complete.innerHTML=complete.disabled?'Reto completado <span>✓</span>':'Completar reto <span>✓</span>'}
renderSpeakingDrill();document.getElementById('drill-listen').addEventListener('click',()=>speak(speakingDrills[state.speakingDrill.index].model,.78));document.getElementById('drill-record').addEventListener('click',()=>{const recorder=document.getElementById('record-button');recorder.scrollIntoView({behavior:'smooth',block:'center'});recorder.click()});document.getElementById('drill-complete').addEventListener('click',()=>{const index=state.speakingDrill.index;if(!state.speakingDrill.completed.includes(index)){state.speakingDrill.completed.push(index);if(state.speakingDrill.completed.length===speakingDrills.length){state.speakingDrill.completed=[];state.speakingDrill.index=0}else state.speakingDrill.index=index+1;saveState();renderSpeakingDrill();markPractice(5,`speaking-drill:${index+1}`)}});

const roleplayScenarios=[
  {title:'Reunión de coordinación',turns:[{speaker:'Elena · equipo técnico',q:'We have different water-demand estimates. How should we compare them?',es:'Tenemos estimaciones distintas de la demanda de agua. ¿Cómo deberíamos compararlas?',model:'I would first check the sources, dates and assumptions behind each estimate. Then we can compare them using the same criteria.'},{speaker:'Rosa · representante local',q:'How will these decisions affect small farmers and households?',es:'¿Cómo afectarán estas decisiones a los pequeños agricultores y a los hogares?',model:'We should explain the possible effects clearly and ask both groups about their priorities before making a recommendation.'},{speaker:'Marco · coordinador',q:'What practical next step do you recommend?',es:'¿Qué siguiente paso práctico recomiendas?',model:'I recommend sharing the data with all the stakeholders, noting what is still uncertain and agreeing on one action to review at our next meeting.'}]},
  {title:'Visita de campo',turns:[{speaker:'Lucía · usuaria de agua',q:'We have noticed more sediment in the canal this month. What will your team do?',es:'Hemos notado más sedimento en el canal este mes. ¿Qué hará su equipo?',model:'Thank you for telling us. We will record where and when this happens, check the monitoring data and discuss the finding with the technical team.'},{speaker:'Tom · especialista',q:'What information should we record at the sampling site?',es:'¿Qué información debemos registrar en el punto de muestreo?',model:'We should record the location, date, time, units and field conditions. If a result looks unusual, we should repeat the measurement and keep both records.'},{speaker:'Lucía · usuaria de agua',q:'When can the community hear about the results?',es:'¿Cuándo podrá la comunidad conocer los resultados?',model:'We can share an initial update after the team checks the results. I will confirm a date and explain any limitations in clear language.'}]},
  {title:'Entrevista de selección',turns:[{speaker:'Interviewer',q:'Why are you interested in this technical assistant role?',es:'¿Por qué te interesa este puesto de asistente técnico?',model:'I am interested because the role combines water management, field activities and collaboration with local stakeholders.'},{speaker:'Interviewer',q:'Tell us about a challenge you faced and how you responded.',es:'Cuéntanos sobre un reto que enfrentaste y cómo respondiste.',model:'During a team assignment, we had incomplete information. I organized what we knew, identified the gaps and helped the team agree on what to verify next.'},{speaker:'Interviewer',q:'What would you focus on during your first month?',es:'¿En qué te enfocarías durante tu primer mes?',model:'I would learn the basin plan, meet the team and community representatives, review current monitoring and organize the available information before suggesting changes.'}]}
];
function renderRoleplay(){const scenario=roleplayScenarios[state.roleplay.scenario];const turn=scenario.turns[state.roleplay.turn];document.getElementById('roleplay-title').textContent=scenario.title;document.getElementById('roleplay-progress').textContent=`TURNO ${state.roleplay.turn+1} / ${scenario.turns.length}`;document.getElementById('roleplay-speaker').textContent=turn.speaker;document.getElementById('roleplay-question').textContent=turn.q;document.getElementById('roleplay-translation').textContent=turn.es;const model=document.getElementById('roleplay-model');model.hidden=!state.roleplay.showModel;model.textContent=turn.model;document.getElementById('roleplay-reveal').innerHTML=state.roleplay.showModel?'Ocultar respuesta modelo <span>−</span>':'Ver respuesta modelo <span>＋</span>';document.getElementById('roleplay-next').textContent=state.roleplay.turn===2?'Terminar diálogo →':'Siguiente turno →'}
renderRoleplay();document.getElementById('roleplay-listen').addEventListener('click',()=>speak(roleplayScenarios[state.roleplay.scenario].turns[state.roleplay.turn].q,.82));document.getElementById('roleplay-record').addEventListener('click',()=>{const recorder=document.getElementById('record-button');recorder.scrollIntoView({behavior:'smooth',block:'center'});recorder.click()});document.getElementById('roleplay-reveal').addEventListener('click',()=>{state.roleplay.showModel=!state.roleplay.showModel;renderRoleplay();localStorage.setItem(STORAGE_KEY,JSON.stringify(state))});document.getElementById('roleplay-next').addEventListener('click',()=>{if(state.roleplay.turn<2){state.roleplay.turn++;state.roleplay.showModel=false;renderRoleplay();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return}const completed=state.roleplay.scenario+1;state.roleplay.scenario=(state.roleplay.scenario+1)%roleplayScenarios.length;state.roleplay.turn=0;state.roleplay.showModel=false;renderRoleplay();saveState();markPractice(8,`roleplay:${completed}`)});

document.getElementById('reading-options').addEventListener('click',event=>{const btn=event.target.closest('button[data-answer]');if(!btn)return;document.querySelectorAll('#reading-options button').forEach(b=>b.classList.remove('correct','incorrect'));readingCorrect=btn.dataset.answer==='true';btn.classList.add(readingCorrect?'correct':'incorrect');document.getElementById('quiz-feedback').textContent=readingCorrect?currentUnit.reading.feedback:'Not quite. Read the passage again and compare each option with its main idea.'});
