const draft=document.getElementById('writing-draft');draft.value=state.drafts[currentUnit.id]||state.draft||'';function updateWordCount(){const count=draft.value.trim()?draft.value.trim().split(/\s+/).length:0;document.getElementById('word-count').textContent=`${count} ${count===1?'palabra':'palabras'}`;state.draft=draft.value;if(currentUnit)state.drafts[currentUnit.id]=draft.value;localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}draft.addEventListener('input',updateWordCount);updateWordCount();installUnitSelectors();renderCourseUnits();renderUnit(currentUnit);renderReadingChallenge(currentUnit);document.getElementById('clear-draft').addEventListener('click',()=>{draft.value='';updateWordCount();draft.focus()});document.getElementById('insert-outline').addEventListener('click',()=>{const outline=currentUnit.writing.structure.map((step,index)=>`${String(index+1).padStart(2,'0')} · ${step}`).join('\n');draft.value=draft.value?`${draft.value}\n\n${outline}`:outline;updateWordCount();draft.focus()});document.getElementById('finish-writing').addEventListener('click',()=>markPractice(15,`writing:${currentUnit.id}`));
document.getElementById('analyze-writing').addEventListener('click',()=>{const range=currentUnit.writing.prompt.match(/\b(\d+)[–-](\d+)\b/);reviewEnglishDraft(draft.value,range?Number(range[1]):80,range?Number(range[2]):120,document.getElementById('writing-coach-result'))});document.getElementById('analyze-mock-writing').addEventListener('click',()=>reviewEnglishDraft(mockDraft.value,150,200,document.getElementById('mock-writing-coach-result')));

document.getElementById('record-button').addEventListener('click',async()=>{if(mediaRecorder?.state==='recording'){mediaRecorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){showToast('La grabación no está disponible en este navegador. Prueba en Chrome o Edge desde localhost.');return}try{recordingStream=await navigator.mediaDevices.getUserMedia({audio:true});recordedChunks=[];mediaRecorder=new MediaRecorder(recordingStream);mediaRecorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data)};mediaRecorder.onstop=()=>{clearInterval(timerInterval);recordingStream?.getTracks().forEach(t=>t.stop());document.getElementById('record-indicator').classList.remove('recording');document.getElementById('record-status').textContent='GRABACIÓN LISTA';const blob=new Blob(recordedChunks,{type:mediaRecorder.mimeType||'audio/webm'});if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(blob);document.getElementById('audio-playback').innerHTML='';const audio=document.createElement('audio');audio.controls=true;audio.src=audioUrl;document.getElementById('audio-playback').append(audio);const save=document.getElementById('save-audio');save.disabled=false;save.onclick=()=>{const a=document.createElement('a');a.href=audioUrl;a.download=`fieldnotes-speaking-${todayKey()}.webm`;a.click()};document.getElementById('record-button').innerHTML='<span>●</span><b>Grabar de nuevo</b>';document.getElementById('record-button').classList.remove('recording');};mediaRecorder.start();recordSeconds=0;document.getElementById('record-button').innerHTML='<span>■</span><b>Detener grabación</b>';document.getElementById('record-button').classList.add('recording');document.getElementById('record-indicator').classList.add('recording');document.getElementById('record-status').textContent='GRABANDO';timerInterval=setInterval(()=>{recordSeconds++;document.getElementById('record-timer').textContent=`${String(Math.floor(recordSeconds/60)).padStart(2,'0')}:${String(recordSeconds%60).padStart(2,'0')}`},1000)}catch(error){showToast(error.name==='NotAllowedError'?'Permite el acceso al micrófono para comenzar.':'No se pudo iniciar el micrófono. Revisa los permisos del navegador.')}});
document.getElementById('speaking-complete').addEventListener('click',()=>markPractice(10,`speaking:${currentUnit.id}`));
const dialog=document.getElementById('vocab-dialog');const reviewDialog=document.getElementById('vocab-review-dialog');let reviewQueue=[];let reviewCurrent=null;document.getElementById('add-vocab').addEventListener('click',()=>dialog.showModal());document.getElementById('vocab-form').addEventListener('submit',e=>{e.preventDefault();const word=document.getElementById('new-word').value.trim();const meaning=document.getElementById('new-meaning').value.trim();const example=document.getElementById('new-example').value.trim();if(state.words.some(w=>w.word.toLowerCase()===word.toLowerCase())){showToast('Esa palabra ya está en tu glosario.');return}state.words.push({word,meaning,example,dueAt:Date.now(),intervalDays:0,repetitions:0});saveState();renderVocab();e.target.reset();dialog.close();showToast('Palabra añadida a tu glosario.')});
function renderVocab(){const list=document.getElementById('vocab-list');list.innerHTML='';state.words.forEach((item,i)=>{const row=document.createElement('div');row.className='vocab-row';const word=document.createElement('strong');word.className='vocab-word';word.textContent=item.word;const meaning=document.createElement('span');meaning.className='vocab-meaning';meaning.textContent=item.meaning;const example=document.createElement('span');example.className='vocab-example';example.textContent=item.example||'Añade una frase propia para recordar la palabra.';const status=document.createElement('small');status.className='vocab-due'+(item.dueAt<=Date.now()?' due-now':'');status.textContent=item.dueAt<=Date.now()?'Pendiente de repaso':`Próximo: ${new Date(item.dueAt).toLocaleDateString('es-PE',{day:'2-digit',month:'short'})}`;const speakBtn=document.createElement('button');speakBtn.className='speak-word';speakBtn.textContent='▶';speakBtn.title='Escuchar';speakBtn.addEventListener('click',()=>speak(item.word));const del=document.createElement('button');del.className='delete-word';del.textContent='×';del.title='Eliminar';del.addEventListener('click',()=>{state.words.splice(i,1);saveState();renderVocab()});row.append(word,meaning,example,status,speakBtn,del);list.append(row)})}
function showReviewCard(){if(!reviewQueue.length){reviewDialog.close();showToast('¡Repaso terminado! Las palabras difíciles volverán antes.');return}reviewCurrent=reviewQueue.shift();document.getElementById('review-progress').textContent=`QUEDAN ${reviewQueue.length+1} TARJETAS`;document.getElementById('review-word').textContent=reviewCurrent.word;document.getElementById('review-example').textContent=reviewCurrent.example||'';document.getElementById('review-meaning').textContent=reviewCurrent.meaning;document.getElementById('review-answer').hidden=true;document.getElementById('reveal-meaning').hidden=false}
function startVocabReview(){reviewQueue=state.words.filter(word=>(word.dueAt||0)<=Date.now()).sort((a,b)=>(a.dueAt||0)-(b.dueAt||0));if(!reviewQueue.length){showToast('No tienes palabras pendientes. Vuelve mañana o añade términos nuevos.');return}reviewDialog.showModal();showReviewCard()}
document.getElementById('review-vocab').addEventListener('click',startVocabReview);document.getElementById('reveal-meaning').addEventListener('click',()=>{document.getElementById('review-answer').hidden=false;document.getElementById('reveal-meaning').hidden=true});document.getElementById('close-review').addEventListener('click',()=>reviewDialog.close());document.querySelector('.review-ratings').addEventListener('click',event=>{const button=event.target.closest('button[data-rating]');if(!button||!reviewCurrent)return;const now=Date.now();if(button.dataset.rating==='again'){reviewCurrent.repetitions=0;reviewCurrent.intervalDays=0;reviewCurrent.dueAt=now+10*60*1000}else if(button.dataset.rating==='hard'){reviewCurrent.repetitions=(reviewCurrent.repetitions||0)+1;reviewCurrent.intervalDays=Math.max(1,(reviewCurrent.intervalDays||0)*1.2);reviewCurrent.dueAt=now+reviewCurrent.intervalDays*86400000}else{reviewCurrent.repetitions=(reviewCurrent.repetitions||0)+1;reviewCurrent.intervalDays=reviewCurrent.intervalDays?Math.min(60,reviewCurrent.intervalDays*2.2):2;reviewCurrent.dueAt=now+reviewCurrent.intervalDays*86400000}saveState();renderVocab();showReviewCard()});
document.getElementById('reset-progress').addEventListener('click',()=>{if(confirm('¿Reiniciar minutos, sesiones y días de práctica? Tu glosario y borrador se conservarán.')){state={...state,minutes:0,sessions:0,streak:0,lastPractice:'',practicedDays:[],completed:[]};saveState();showToast('Progreso reiniciado.')}});
document.getElementById('export-progress').addEventListener('click',()=>{const backup={format:'fieldnotes-english-backup',version:1,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`fieldnotes-english-${todayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Copia de seguridad descargada.')});
const importFile=document.getElementById('import-progress-file');document.getElementById('import-progress').addEventListener('click',()=>importFile.click());importFile.addEventListener('change',async()=>{const file=importFile.files?.[0];if(!file)return;try{const backup=JSON.parse(await file.text());const restored=backup?.format==='fieldnotes-english-backup'&&backup?.version===1?backup.state:null;if(!restored||typeof restored!=='object'||!Array.isArray(restored.words)||!Array.isArray(restored.completed)||!Array.isArray(restored.practicedDays)||!restored.mock||!Array.isArray(restored.mock.writtenAttempts)||!Array.isArray(restored.mock.oralAttempts))throw new Error('invalid backup');if(!confirm('Restaurar esta copia reemplazará el progreso y el glosario guardados en este navegador. ¿Continuar?'))return;localStorage.setItem(STORAGE_KEY,JSON.stringify({...defaults,...restored,mock:{...defaults.mock,...restored.mock}}));location.reload()}catch{showToast('No pude leer la copia. Elige un archivo JSON exportado por Fieldnotes English.')}finally{importFile.value=''}});

const mockDraft=document.getElementById('mock-writing-draft');mockDraft.value=state.mock.writtenText||'';let writtenTimer=null;let oralTimer=null;const mockDuration=30*60*1000;const oralDuration=90*1000;function clockText(ms){const seconds=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}function updateMockWordCount(){const count=mockDraft.value.trim()?mockDraft.value.trim().split(/\s+/).length:0;document.getElementById('mock-word-count').textContent=`${count} palabras`;state.mock.writtenText=mockDraft.value;localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}mockDraft.addEventListener('input',updateMockWordCount);updateMockWordCount();function tickWritten(){if(!state.mock.writtenDeadline){document.getElementById('written-clock').textContent='30:00';clearInterval(writtenTimer);writtenTimer=null;return}const remaining=state.mock.writtenDeadline-Date.now();document.getElementById('written-clock').textContent=clockText(remaining);if(remaining<=0){state.mock.writtenDeadline=null;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));clearInterval(writtenTimer);writtenTimer=null;document.getElementById('written-result').textContent='Se acabó el tiempo. Revisa tu respuesta y guarda el intento.';showToast('Terminó el tiempo del simulacro escrito.')}}function startWrittenTimer(){if(state.mock.writtenDeadline&&state.mock.writtenDeadline>Date.now()){showToast('El reloj ya está en marcha.');return}state.mock.writtenDeadline=Date.now()+mockDuration;['mock-addressed','mock-structure','mock-support','mock-checked'].forEach(id=>document.getElementById(id).checked=false);document.getElementById('written-result').textContent='Reloj iniciado. Concéntrate en responder cada parte.';localStorage.setItem(STORAGE_KEY,JSON.stringify(state));clearInterval(writtenTimer);tickWritten();writtenTimer=setInterval(tickWritten,1000)}document.getElementById('start-written-mock').addEventListener('click',startWrittenTimer);document.getElementById('save-written-mock').addEventListener('click',()=>{const text=mockDraft.value.trim();if(!text){showToast('Escribe una respuesta antes de guardar el intento.');return}const wordCount=text.split(/\s+/).length;const reviewIds=['mock-addressed','mock-structure','mock-support','mock-checked'];const reviewScore=reviewIds.filter(id=>document.getElementById(id).checked).length;const deadline=state.mock.writtenDeadline;const elapsed=deadline?Math.max(1,Math.ceil((mockDuration-(deadline-Date.now()))/60000)):1;state.mock.writtenAttempts.push({date:new Date().toISOString(),words:wordCount,reviewScore,text});state.mock.writtenAttempts=state.mock.writtenAttempts.slice(-10);renderWrittenHistory();state.mock.writtenDeadline=null;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));clearInterval(writtenTimer);writtenTimer=null;tickWritten();document.getElementById('written-result').textContent=`Intento guardado: ${wordCount} palabras · autoevaluación ${reviewScore}/4. No es una calificación automática; úsala para elegir qué revisar.`;markPractice(elapsed,`mock-writing-${state.mock.writtenAttempts.length}`)});
const introUnit=courseUnits.find(unit=>unit.id==='introduction');const advancedBriefingUnit=courseUnits.find(unit=>unit.id==='advanced-briefing');const oralMockPrompts=[introUnit.speaking[0],advancedBriefingUnit.speaking[0],advancedBriefingUnit.speaking[2]];function renderOralMockQuestion(){const index=Math.min(2,Math.max(0,state.mock.oralIndex));state.mock.oralIndex=index;document.getElementById('oral-mock-question').textContent=oralMockPrompts[index].q;document.getElementById('oral-mock-translation').textContent=oralMockPrompts[index].es;document.getElementById('oral-mock-progress').textContent=`QUESTION ${index+1} / 3`;document.getElementById('next-oral-question').textContent=index===2?'Terminar entrevista ✓':'Siguiente pregunta →'}function tickOral(){if(!state.mock.oralDeadline){document.getElementById('oral-clock').textContent='01:30';clearInterval(oralTimer);oralTimer=null;return}const remaining=state.mock.oralDeadline-Date.now();document.getElementById('oral-clock').textContent=clockText(remaining);if(remaining<=0){state.mock.oralDeadline=null;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));clearInterval(oralTimer);oralTimer=null;showToast('Terminó el tiempo para esta respuesta.')}}function startOralTimer(){if(state.mock.oralDeadline&&state.mock.oralDeadline>Date.now()){showToast('El reloj oral ya está en marcha.');return}state.mock.oralActive=true;state.mock.oralIndex=0;['oral-direct','oral-example','oral-clear'].forEach(id=>document.getElementById(id).checked=false);state.mock.oralDeadline=Date.now()+oralDuration;renderOralMockQuestion();document.getElementById('oral-result').textContent='Responde con tus propias palabras; luego usa la grabadora para escucharte.';clearInterval(oralTimer);tickOral();oralTimer=setInterval(tickOral,1000);localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}document.getElementById('start-oral-mock').addEventListener('click',startOralTimer);document.getElementById('next-oral-question').addEventListener('click',()=>{if(!state.mock.oralActive){showToast('Inicia la entrevista para empezar.');return}if(state.mock.oralIndex<2){state.mock.oralIndex++;state.mock.oralDeadline=Date.now()+oralDuration;renderOralMockQuestion();clearInterval(oralTimer);tickOral();oralTimer=setInterval(tickOral,1000);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return}state.mock.oralDeadline=null;state.mock.oralActive=false;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));clearInterval(oralTimer);oralTimer=null;tickOral();const score=['oral-direct','oral-example','oral-clear'].filter(id=>document.getElementById(id).checked).length;state.mock.oralAttempts.push({date:new Date().toISOString(),score});state.mock.oralAttempts=state.mock.oralAttempts.slice(-10);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderOralHistory();document.getElementById('oral-result').textContent=`Entrevista terminada. Autoevaluación: ${score}/3. Repite las respuestas que aún te cuesten.`;markPractice(15,`mock-oral-${state.mock.oralAttempts}`)});document.getElementById('oral-mock-listen').addEventListener('click',()=>speak(oralMockPrompts[state.mock.oralIndex].q,.82));document.getElementById('open-mock-recorder').addEventListener('click',()=>{const question=oralMockPrompts[state.mock.oralIndex];const unit=courseUnits.find(item=>item.speaking.some(prompt=>prompt.q===question.q));if(!unit)return;selectUnit(unit.id);const promptPosition=unit.speaking.findIndex(prompt=>prompt.q===question.q);setSpeakingPrompt(promptPosition);navigate('speaking')});document.getElementById('mock-tab-writing').addEventListener('click',()=>{document.getElementById('mock-writing-panel').hidden=false;document.getElementById('mock-speaking-panel').hidden=true;document.getElementById('mock-tab-writing').classList.add('active');document.getElementById('mock-tab-speaking').classList.remove('active')});document.getElementById('mock-tab-speaking').addEventListener('click',()=>{document.getElementById('mock-writing-panel').hidden=true;document.getElementById('mock-speaking-panel').hidden=false;document.getElementById('mock-tab-speaking').classList.add('active');document.getElementById('mock-tab-writing').classList.remove('active')});renderOralMockQuestion();if(state.mock.writtenDeadline> Date.now()){tickWritten();writtenTimer=setInterval(tickWritten,1000)}if(state.mock.oralDeadline>Date.now()){renderOralMockQuestion();tickOral();oralTimer=setInterval(tickOral,1000)}
