function renderWrittenHistory(){const list=document.getElementById('written-history');if(!list)return;list.innerHTML='';if(!state.mock.writtenAttempts.length){list.textContent='Todavía no hay intentos guardados.';return}state.mock.writtenAttempts.slice().reverse().forEach((attempt,index)=>{const details=document.createElement('details');const summary=document.createElement('summary');const date=new Date(attempt.date).toLocaleDateString('es-PE',{day:'2-digit',month:'short',year:'numeric'});summary.textContent=`Intento ${state.mock.writtenAttempts.length-index} · ${date} · ${attempt.words} palabras · autoevaluación ${attempt.reviewScore}/4`;const text=document.createElement('p');text.textContent=attempt.text;details.append(summary,text);list.append(details)})}
